using System;using System.Linq;using System.Globalization;using BeamScheduleFormatter;
class ManualSlabTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,string why){Check(Math.Abs(a-b)<1e-7,why);}static void Reject(Action work,string why){bool failed=false;try{work();}catch{failed=true;}Check(failed,why);}static string[][] Groups(){return Enumerable.Range(0,9).Select(n=>new[]{"","Spacing (mm)",""}).ToArray();}
 static void Main(){var cfg=new LengthConfiguration{Name="Manual test",GradeSmall=40,GradeLarge=60,FySmall=275,FyLarge=420,Input=new LengthInput{Fc=28,Round=25,Simplified=true}};var groups=Groups();groups[0]=new[]{"12","Spacing (mm)","150"};groups[2]=new[]{"16","Number of bars","9"};var schedule=ManualSlabSchedule.Create("manual-s1","125",groups);Check(schedule.Manual&&schedule.Mark=="MANUAL-S1","Manual source is identified and normalized");string xml=ManualSlabSchedule.Write(schedule);var restored=ManualSlabSchedule.ReadSource(xml).Single();Check(restored.Bars[2].ExplicitCount==9&&restored.Bars[2].SpacingMm==0,"Count roundtrip does not invent equivalent spacing");Check(restored.Bars[0].SpacingMm==150&&restored.Bars.Count(b=>b!=null)==2,"Only entered groups restored");var q=SlabEstimatorEngine.Calculate(restored,"Manual room",3,4,2,true,0,20,cfg,0,0,0,0,0,0);Near(q.Measures.ConcreteTotal,3,"Manual thickness reaches concrete takeoff without DXF");Near(q.Measures.SoffitTotal,24,"Manual slab includes elevated forms");var shortBars=q.Steel.Result.Lines.Single(l=>l.Part=="Bottom short FULL");var longBars=q.Steel.Result.Lines.Single(l=>l.Part=="Bottom long FULL");Check(shortBars.PiecesPerBeam==28&&longBars.PiecesPerBeam==9,"Spacing-derived and explicitly counted directions remain independent");Near(longBars.Metres,longBars.CutLength*9*2,"Panel quantity multiplied once");Check(longBars.Formula.Contains("9 entered bars"),"Report explains entered count instead of division by zero spacing");Check(CommercialBars.Allocate(new[]{q.Steel},cfg,new[]{6.0}).All(a=>a.Choice!=null),"Manual steel joins ordinary stock purchase allocation");groups[4]=new[]{"12","Number of bars","8"};groups[8]=new[]{"10","Number of bars","4"};schedule=ManualSlabSchedule.Create("S2","150",groups);q=SlabEstimatorEngine.Calculate(schedule,"Top support",3,4,1,true,0,20,cfg,2,0,0,0,0,0);Check(q.Steel.Result.Lines.Single(l=>l.Part=="Top over LONG CONT").PiecesPerBeam==16,"Top explicit count multiplied by actual support count");Check(q.Steel.Result.Lines.Single(l=>l.Part=="Top distribution LONG CONT").PiecesPerBeam==8,"Distribution count follows each support strip");groups[2][2]="2.5";Reject(()=>ManualSlabSchedule.Create("S3","125",groups),"Fractional manual count rejected");groups[2][2]="1";Reject(()=>ManualSlabSchedule.Create("S3","125",groups),"Single-bar mat count rejected");Reject(()=>ManualSlabSchedule.Create("S3","125",Groups()),"Empty reinforcement is not silently quantified");Reject(()=>ManualSlabSchedule.Create("S3","0",Groups()),"Nonpositive thickness rejected");Reject(()=>ManualSlabSchedule.Read(xml.Replace("group=\"0\"","group=\"9\"")),"Invalid saved group rejected");Reject(()=>ManualSlabSchedule.Count(new SlabBar{ExplicitCount=8},double.NaN,20),"Invalid geometry rejected even with explicit count");Console.WriteLine("PASS: "+checks+" manual slab persistence, independent inputs, support multipliers, concrete/forms and purchase checks");}
}
